import ts from 'typescript';
export async function transform({source,target,compiler='typescript'}){
  if(compiler!=='typescript')throw Error('Unsupported compiler');
  const selected={es2015:ts.ScriptTarget.ES2015,es2020:ts.ScriptTarget.ES2020}[target];if(selected===undefined)throw Error('Unsupported target');
  const result=ts.transpileModule(source,{compilerOptions:{target:selected},reportDiagnostics:true});
  const diagnostics=(result.diagnostics||[]).map(item=>{const position=item.file&&item.start!==undefined?item.file.getLineAndCharacterOfPosition(item.start):null;return{message:ts.flattenDiagnosticMessageText(item.messageText,'\n'),line:position?position.line+1:null,column:position?position.character+1:null};});
  return{code:diagnostics.length?'':result.outputText,diagnostics};
}
